#include<bits/stdc++.h>
using namespace std;
using ll=long long;

ll dp[505][505];

int main()
{
    cin.tie(0)->sync_with_stdio(0);
    int t;cin>>t;
    for(int tc=0;tc<t;tc++)
    {
        ll n;cin>>n;
        vector<ll>vec(n);
        for(ll&i:vec)cin>>i;
        for(int i=0;i<n;i++)
        {
            for(int j=0;j<n;j++)dp[i][j]=-1e18;
        }
        auto value=[&](ll i,ll j,ll k)
        {
            return i*j*k;
        };
        for(int len=1;len<=n;len++)
        {
            for(int L=0;L<n;L++)
            {
                ll ans=0;
                ll R=(L+len-1)%n;
                if(len<=2)
                {
                    dp[L][R]=0;
                    continue;
                }
                if(len==3)
                {
                    dp[L][R]=max(0LL,value(vec[L],vec[(L+1)%n],vec[R]));
                    continue;
                }
                for(int i=(L+1)%n;i!=R;i=(i+1)%n)
                {
                    ll val=value(vec[L],vec[i],vec[R]);
                    if(i!=(L+1)%n)val+=dp[(L+1)%n][(i+n-1)%n];
                    if(i!=(R+n-1)%n)val+=dp[(i+1)%n][(R+n-1)%n];
                    ans=max(ans,val);
                }
                for(int i=L;i!=R;i=(i+1)%n)
                {
                    ans=max(ans,dp[L][i]+dp[(i+1)%n][R]);
                }
                dp[L][R]=ans;
            }
        }
        ll ans=0;
        for(int i=0;i<n;i++)
        {
            ans=max(ans,dp[i][(i+n-1)%n]);
        }
        cout<<ans<<"\n";
    }
}

int msb(int i)
{
    return i ? __builtin_clz(1) - __builtin_clz(i) : -1;
}

void xortriangle(int x)
{
    int y = x + 1;  // if all bits are set, then x + 1 only has 1 bit set;
    if (!(x & (x - 1)) || !(y & (y - 1))) cout<<-1<<'\n';
    else cout<<((1 << msb(x)) - 1)<<'\n';
}
